import {installUrbanGlass} from './urban-assets.js?v=60';
import {ruralTextures} from './rural-textures.js?v=60';
import * as T from './vendor/three.module.min.js';
import {returnProgress,RETURN_LENGTH} from './milling-return-layout.js';
const tex={};let loading;export const returnTime={value:0},returnPlayer={value:new T.Vector3()};
export function initializeMillingTextures(){if(loading)return loading;const list=['asphalt','clay','brick','burlap','kraft','wood','steel'].flatMap(n=>[n,n+'-normal',n+'-rough']).concat('plants','glass','backdrop-a','backdrop-b','warning-no','warning-staff','warning-vehicles','green','green-normal','green-rough','yellow','yellow-normal','yellow-rough'),loader=new T.TextureLoader();let next=0;return loading=Promise.all(Array.from({length:4},async()=>{while(next<list.length){const n=list[next++],t=await loader.loadAsync(new URL(n==='glass'?'./textures/urban-v49/glass-blue-black.webp':'./textures/return-alley/'+n+'.webp',import.meta.url).href);t.colorSpace=/-normal|-rough/.test(n)?T.NoColorSpace:T.SRGBColorSpace;t.wrapS=t.wrapT=['plants','burlap','kraft','backdrop','warning'].includes(n.split('-')[0])?T.ClampToEdgeWrapping:T.MirroredRepeatWrapping;t.anisotropy=4;tex[n]=t;}}));}
export function millingMaterials(){const surface=(n,color=0xffffff,r=.9,metalness=0)=>new T.MeshStandardMaterial({name:'Milling / '+n,map:tex[n],normalMap:tex[n+'-normal'],normalScale:new T.Vector2(.25,.25),roughnessMap:tex[n+'-rough'],color,roughness:r,metalness});
 const m={asphalt:surface('asphalt'),brick:surface('brick',0xb0aaa2),steel:surface('steel',0x99a7a5,.7,.4),wood:surface('wood',0xc4bbac),burlap:surface('burlap'),kraft:surface('kraft'),clay:surface('clay',0xa8956b),metal:surface('steel',0x25312f,.62,.65),cement:surface('clay',0x98968a),floor:surface('asphalt',0xd2d1c7),flour:surface('clay',0xf5f0df,.95),lamp:surface('kraft',0xffe0a6,.65)};
 m.green=surface('green',0xffffff,.68,.35);m.yellow=surface('yellow');
 for(const n of['warning-no','warning-staff','warning-vehicles']){m[n]=surface(n,0xffffff,.8,.22);}
 for(const n of['backdrop-a','backdrop-b']){m[n]=new T.MeshBasicMaterial({map:tex[n],alphaTest:.02,transparent:true,side:T.DoubleSide,color:0xd2d5cc,depthWrite:false,fog:true});m[n].onBeforeCompile=s=>{s.fragmentShader=s.fragmentShader.replace('#include <fog_fragment>','#ifdef USE_FOG\nfloat backdropFog=smoothstep(fogNear,fogFar,vFogDepth);gl_FragColor.a*=1.-backdropFog;\n#endif');};}
 m.flour.transparent=true;m.flour.depthWrite=false;m.flour.polygonOffset=true;m.flour.polygonOffsetFactor=-1;m.flour.onBeforeCompile=s=>{s.fragmentShader=s.fragmentShader.replace('#include <alphatest_fragment>','#include <alphatest_fragment>\ndiffuseColor.a*=pow(1.-smoothstep(.1,.5,length(vMapUv-vec2(.5))),1.4)*.52;');};
 m.lamp.emissive.set(0xf4bb72);m.lamp.emissiveIntensity=.35;
 m.glass=new T.MeshStandardMaterial({name:'Dusty wired glazing / overcast reflection',color:0x6b8287,roughness:.44,metalness:.14});
 installUrbanGlass(m.glass);m.glass.map=tex.glass;m.glass.roughness=.36;m.glass.metalness=.3;
 m.plants=new T.MeshStandardMaterial({name:'Generated dry grass / crossed cards',map:tex.plants,alphaTest:.45,side:T.DoubleSide,roughness:.98,color:0xc3aa70});
 m.plants.onBeforeCompile=s=>{s.uniforms.uReturnTime=returnTime;s.vertexShader='uniform float uReturnTime;\n'+s.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\ntransformed.x+=sin(uReturnTime*.72+position.z*.43)*.027*uv.y*uv.y;');};
 m.floor.onBeforeCompile=s=>{s.uniforms.u_returnProgress=returnProgress;s.uniforms.uReturnTime=returnTime;s.uniforms.uReturnClay={value:tex.clay};s.uniforms.uReturnPath={value:ruralTextures.path};s.uniforms.uReturnTurf={value:ruralTextures.turf};s.uniforms.uReturnClayNormal={value:tex['clay-normal']};s.vertexShader='attribute vec2 returnRoad; varying vec2 vReturnRoad; varying vec3 vReturnPosition;\n'+s.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\nvReturnRoad=returnRoad;vReturnPosition=position;');s.fragmentShader='uniform float u_returnProgress;uniform float uReturnTime;uniform sampler2D uReturnClay;uniform sampler2D uReturnClayNormal;uniform sampler2D uReturnPath;uniform sampler2D uReturnTurf;varying vec2 vReturnRoad;varying vec3 vReturnPosition;\nfloat millingHash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}\n'+s.fragmentShader;
 s.fragmentShader=s.fragmentShader.replace('#include <map_fragment>',`vec2 uvR=vMapUv;vec3 aa=texture2D(map,uvR).rgb,bb=texture2D(uReturnClay,uvR*.83).rgb;float t=clamp(vReturnRoad.x/${RETURN_LENGTH.toFixed(1)},0.,1.);float slip=smoothstep(.70,.90,u_returnProgress);vec2 noiseP=vReturnPosition.xz*.63;vec2 ni=floor(noiseP),nf=fract(noiseP);nf=nf*nf*(3.-2.*nf);float noise=mix(mix(millingHash(ni),millingHash(ni+vec2(1.,0.)),nf.x),mix(millingHash(ni+vec2(0.,1.)),millingHash(ni+vec2(1.,1.)),nf.x),nf.y);float soil=smoothstep(.30,.73,t+(aa.r-aa.b)*.22+(noise-.5)*.14);float across=abs(vReturnRoad.y);float track=exp(-pow((across-.87)/.30,4.));float dust=(1.-soil)*smoothstep(.46,.82,aa.r)*.56;float dragged=(1.-smoothstep(.62,.91,t))*smoothstep(.17,.36,t)*exp(-pow((across-1.20-.17*sin(vReturnRoad.x*.13))/.16,2.))*smoothstep(.26,.74,noise)*.64;float puddle=(1.-soil)*smoothstep(1.56,1.82,across)*(1.-smoothstep(2.02,2.24,across))*(1.-smoothstep(.30,.62,sin(vReturnRoad.x*.34)*.5+.5));diffuseColor.rgb*=mix(aa,bb,soil);diffuseColor.rgb=mix(diffuseColor.rgb,vec3(.69,.67,.59),clamp(dust+dragged*.57,0.,.78));vec3 nativePath=texture2D(uReturnPath,uvR*.87).rgb;vec3 turf=texture2D(uReturnTurf,uvR*1.2).rgb*.67;float grass=smoothstep(1.22,1.76,across)+(1.-smoothstep(.25,.55,across))*.75;diffuseColor.rgb=mix(diffuseColor.rgb,mix(nativePath*.88,turf,clamp(grass,0.,1.)*.76),smoothstep(.62,.94,t)*(.94+.06*slip));diffuseColor.rgb*=1.-track*soil*.16;diffuseColor.rgb=mix(diffuseColor.rgb,vec3(.30,.34,.35),puddle*.28);`);
 s.fragmentShader=s.fragmentShader.replace('#include <normal_fragment_maps>',`#include <normal_fragment_maps>\nvec3 clayNormal=texture2D(uReturnClayNormal,vMapUv*.83).xyz*2.-1.;normal=normalize(mix(normal,normal+vec3(clayNormal.xy*.065,0.),smoothstep(.3,.75,vReturnRoad.x/${RETURN_LENGTH.toFixed(1)})));`);
 s.fragmentShader=s.fragmentShader.replace('#include <roughnessmap_fragment>',`#include <roughnessmap_fragment>\nroughnessFactor=mix(.95,roughnessFactor,.25);roughnessFactor=mix(roughnessFactor,.14,puddle);`);
 // Thin wet slurry receives the same dielectric sky reflection, without another ground plane.
 s.fragmentShader=s.fragmentShader.replace('#include <opaque_fragment>',`float wetF=pow(1.-abs(dot(normal,normalize(vViewPosition))),5.);outgoingLight=mix(outgoingLight,vec3(.47,.51,.52),puddle*(.05+wetF*.20));\n#include <opaque_fragment>`);
 };m.floor.customProgramCacheKey=()=> 'milling-return-two-normal-splat-84';return m;}
export function applyReturnMirage(material,positionS){const prior=material.onBeforeCompile;material.onBeforeCompile=s=>{prior?.(s);s.uniforms.u_returnProgress=returnProgress;s.uniforms.uMillingClosure={value:tex.steel};s.vertexShader='uniform float u_returnProgress;varying float vMillingHeight;\n'+s.vertexShader;s.vertexShader=s.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\nvMillingHeight=position.y;transformed.y=min(transformed.y,2.4)+max(0.,transformed.y-2.4)*(1.-.76*smoothstep(.40,.65,u_returnProgress));');s.fragmentShader='uniform float u_returnProgress;uniform sampler2D uMillingClosure;varying float vMillingHeight;\n'+s.fragmentShader;s.fragmentShader=s.fragmentShader.replace('#include <opaque_fragment>',`#if defined(USE_MAP)\nfloat closure=smoothstep(.42,.62,u_returnProgress)*smoothstep(2.3,3.5,vMillingHeight);outgoingLight=mix(outgoingLight,texture2D(uMillingClosure,vMapUv).rgb*.30,closure*.86);\n#endif\n#include <opaque_fragment>`);s.fragmentShader=s.fragmentShader.replace('#include <alphatest_fragment>',`#include <alphatest_fragment>\nfloat dustThreshold=smoothstep(.66,.80,u_returnProgress)*${positionS<225?'1.0':'0.0'};if(fract(dot(gl_FragCoord.xy,vec2(.75487766,.56984029)))<dustThreshold)discard;`);};material.customProgramCacheKey=()=> 'milling-return-mirage-'+positionS;return material;}
